1272	// ---------------------------------------------------------------------------
1273	// IDLE-GUARD — runner-level, self-issued filler work. When the bot has had no
1274	// running task for IDLE_GUARD_THRESHOLD_MS and is connected, the ticker below
1275	// self-issues an 'idle-guard' task (through the normal startTask/task-mutex
1276	// path, so it shows up in /status like anything else) that loops forever:
1277	// sweep drops -> deposit surplus at depot A if close enough and carrying
1278	// enough, else a short pause -> repeat. Deliberately preemptible: any real
1279	// task request from a driver instantly cancels it (see the
1280	// preemptingIdleGuard branch in startTask above) with no 409 and no force
1281	// flag needed. deathCount/poisonedTargets/state.connected etc. are never
1282	// touched here — idle-guard is just another task from their point of view.
1283	// ---------------------------------------------------------------------------
1284	
1285	const IDLE_GUARD_THRESHOLD_MS = 90000; // EMERGENCY REVERT: 15s machine-gunned the task mutex and locked out ALL driver tasks fleet-wide. Visible-idle answer = smarter filler, not faster trigger.
1286	const IDLE_GUARD_TICK_MS = 5000;
1287	
1288	// DRIVER-AWARE TOGGLE (issue #6) — an LLM driver's own think-gaps regularly
1289	// exceed IDLE_GUARD_THRESHOLD_MS and are normal, not abandonment; without a
1290	// way to say "I'm still driving, just thinking" the guard self-issues a
1291	// filler task underneath an active driver (two-commanders problem). POST
1292	// /idleguard {"on":false} lets a driver quiet the guard for its own session.
1293	// SAFETY TTL below is the backstop for a driver that goes off flag AND then
1294	// vanishes for real — a bot must never end up permanently unguarded just
1295	// because the driver that disabled it crashed or forgot.
1296	let idleGuardEnabled = true;
1297	let idleGuardOffLoggedAt = 0;
1298	const IDLE_GUARD_OFF_LOG_INTERVAL_MS = 180000; // log the "skipping" line at most once per 3min while off, not every 5s tick
1299	let lastHttpRequestAt = Date.now(); // stamped once per request in handleRequest; safety TTL below measures driver silence from this
1300	const IDLE_GUARD_SAFETY_TTL_MS = 15 * 60 * 1000; // 15min with zero incoming HTTP requests while off -> auto re-arm
1301	// Depot chest A — must stay in sync with skills.js's own DEPOT_POS constant
1302	// (kept separate rather than exported/imported to avoid coupling this
1303	// runner-only scheduling concern to skills.js's module surface).
1304	const IDLE_GUARD_DEPOT_POS = { x: 11, y: 89, z: 55 };
1305	const IDLE_GUARD_DEPOT_RADIUS = 40;
1306	const IDLE_GUARD_SURPLUS_THRESHOLD = 8;
1307	
1308	function distance3(a, b) {
1309	  const dx = a.x - b.x;
1310	  const dy = a.y - b.y;
1311	  const dz = a.z - b.z;
1312	  return Math.sqrt(dx * dx + dy * dy + dz * dz);
1313	}
1314	
1315	// Sleeps up to ms, but checks ctx.isCancelled() every 500ms and returns
1316	// early the instant a preemption lands — this is what makes the "else pause
1317	// 20s" branch of the cycle instantly preemptible instead of blocking a
1318	// driver's request behind a dumb setTimeout.
1319	async function cancellableSleep(ms, ctx) {
1320	  const step = 500;
1321	  let waited = 0;
1322	  while (waited < ms) {
1323	    if (ctx.isCancelled?.()) return;
1324	    await sleep(Math.min(step, ms - waited));
1325	    waited += step;
1326	  }
1327	}
1328	
1329	async function idleGuardCycle(task, ctx) {
1330	  let cycles = 0;
1331	  while (!ctx.isCancelled() && !ctx.isStaleGeneration?.()) {
1332	    const b = bot;
1333	    if (!b || !b.entity) break;
1334	    cycles++;
1335	    ctx.setDetail(`idle-guard: cycle ${cycles}`);
1336	
1337	    await announce('status', '(idle-guard) sweeping for drops');
1338	    try {
1339	      await skills.collectDrops(b, { radius: 12 }, ctx);
1340	    } catch (err) {
1341	      ctx.log('warn', `idle-guard: collectDrops failed: ${err.message}`);
1342	    }
1343	    if (ctx.isCancelled()) break;
1344	    if (!bot || !bot.entity) break;
1345	
1346	    const nonTool = bot.inventory.items().filter((it) => !skills.isToolLike(it.name));
1347	    const nonToolCount = nonTool.reduce((sum, it) => sum + it.count, 0);
1348	    const dist = distance3(bot.entity.position, IDLE_GUARD_DEPOT_POS);
1349	
1350	    if (nonToolCount > IDLE_GUARD_SURPLUS_THRESHOLD && dist <= IDLE_GUARD_DEPOT_RADIUS) {
1351	      const names = [...new Set(nonTool.map((it) => it.name))];
1352	      await announce('status', `(idle-guard) depositing ${nonToolCount} surplus items at depot`);
1353	      try {
1354	        const result = await skills.depositToChest(bot, { pos: IDLE_GUARD_DEPOT_POS, items: names }, ctx);
1355	        const deposited = result.deposited || [];
1356	        if (deposited.length) {
1357	          // DEPOT ledger, one line per item, in the DRIVER_GUIDE DEPOT format.
1358	          // Still emitted through smartChat and still worded identically —
1359	          // but since the DEPOT de-chat decree (2026-09-01, see
1360	          // PROTOCOL_PREFIX above) "DEPOT " no longer matches the protocol
1361	          // branch, so these now route through announce('status') to the
1362	          // Discord status feed instead of public white chat.
1363	          for (const d of deposited) {
1364	            await smartChat(`DEPOT +${d.count} ${d.name} (chest A)`);
1365	          }
1366	        } else {
1367	          await announce('status', '(idle-guard) deposited nothing (chest full?)');
1368	        }
1369	      } catch (err) {
1370	        ctx.log('warn', `idle-guard: deposit failed: ${err.message}`);
1371	        await announce('status', `(idle-guard) deposit attempt failed: ${err.message}`);
1372	      }
1373	    } else {
1374	      await announce('status', '(idle-guard) nothing to do, pausing');
1375	      await cancellableSleep(20000, ctx);
1376	    }
1377	  }
1378	  return { cycles };
1379	}
1380	
1381	function maybeStartIdleGuard() {
1382	  if (!idleGuardEnabled) {
1383	    const now = Date.now();
1384	    if (now - idleGuardOffLoggedAt > IDLE_GUARD_OFF_LOG_INTERVAL_MS) {
1385	      idleGuardOffLoggedAt = now;
1386	      logLine('info', 'idle-guard: disabled by driver, skipping fire');
1387	    }
1388	    return;
1389	  }
1390	  if (!state.connected || !bot?.entity) return;
1391	  const isIdle = !state.currentTask || state.currentTask.state !== 'running';
1392	  if (!isIdle) return;
1393	  if (Date.now() - idleSince < IDLE_GUARD_THRESHOLD_MS) return;
1394	  startTask('idle-guard', idleGuardCycle, { source: 'idle-guard' }).catch((err) => {
1395	    if (!err?.busy) logLine('error', `idle-guard: failed to self-start: ${err?.message ?? err}`);
1396	  });
1397	}
1398	
1399	// SAFETY TTL — if a driver disabled the guard and then goes silent (crashed,
1400	// lost connection, forgot) for IDLE_GUARD_SAFETY_TTL_MS with zero incoming
1401	// HTTP requests of ANY kind, the guard re-arms itself unconditionally. An
1402	// abandoned bot must never sit unguarded forever just because the last thing
1403	// a driver did was turn the guard off.
1404	function checkIdleGuardSafetyTTL() {
1405	  if (idleGuardEnabled) return;
1406	  if (Date.now() - lastHttpRequestAt < IDLE_GUARD_SAFETY_TTL_MS) return;
1407	  idleGuardEnabled = true;
1408	  logLine('warn', 'idle-guard: re-armed after 15min driver silence (safety TTL)');
1409	  pushEvent('idle-guard', 're-armed after 15min driver silence');
1410	}
1411	
1412	setInterval(() => {
1413	  try {
1414	    checkIdleGuardSafetyTTL();
1415	    maybeStartIdleGuard();
1416	  } catch (err) {
1417	    logLine('error', `idle-guard tick error: ${err?.stack ?? err}`);
1418	  }
1419	}, IDLE_GUARD_TICK_MS);

