import fs from 'node:fs';
import path from 'node:path';

const DEATHS_DIR = '/tmp/deathtest/deaths';
fs.mkdirSync(DEATHS_DIR, { recursive: true });
const name = 'TestBot';
const deathsFilePath = path.join(DEATHS_DIR, `${name}.json`);
const deathLedger = [];
const state = { deathCount: 0, lastDeath: null };
const logs = [];
function logLine(level, msg) { logs.push(`[${level}] ${msg}`); }

function persistDeaths() {
  try {
    fs.writeFileSync(deathsFilePath, JSON.stringify(
      { name, deathCount: state.deathCount, lastDeath: state.lastDeath, deaths: deathLedger.slice(-100) }, null, 2));
  } catch (err) { logLine('warn', `death ledger persist failed: ${err?.message ?? err}`); }
}
function loadDeaths() {
  try {
    const raw = JSON.parse(fs.readFileSync(deathsFilePath, 'utf8'));
    if (typeof raw?.deathCount === 'number') state.deathCount = raw.deathCount;
    if (raw?.lastDeath) state.lastDeath = raw.lastDeath;
    if (Array.isArray(raw?.deaths)) deathLedger.push(...raw.deaths.slice(-100));
    logLine('info', `death ledger loaded: deathCount=${state.deathCount}, entries=${deathLedger.length}`);
  } catch (err) {
    logLine('warn', `death ledger: no usable file at ${deathsFilePath} (${err?.code ?? err?.message ?? err}) — starting fresh`);
  }
}

// 1. boot with no file
loadDeaths();
console.log('BOOT1 (no file):', JSON.stringify(state), logs.pop());

// 2. simulate a death, persist
state.deathCount++;
state.lastDeath = { pos: { x: 1, y: 64, z: 2 }, ts: new Date().toISOString() };
deathLedger.push({ pos: state.lastDeath.pos, ts: state.lastDeath.ts, dimension: 'minecraft:overworld', cause: null, taskKind: 'chop' });
persistDeaths();
console.log('AFTER DEATH persisted, file exists:', fs.existsSync(deathsFilePath));
console.log('file contents:', fs.readFileSync(deathsFilePath, 'utf8'));

// 3. simulate restart: fresh state, reload
const state2 = { deathCount: 0, lastDeath: null };
const deathLedger2 = [];
function loadDeaths2() {
  try {
    const raw = JSON.parse(fs.readFileSync(deathsFilePath, 'utf8'));
    if (typeof raw?.deathCount === 'number') state2.deathCount = raw.deathCount;
    if (raw?.lastDeath) state2.lastDeath = raw.lastDeath;
    if (Array.isArray(raw?.deaths)) deathLedger2.push(...raw.deaths.slice(-100));
    logLine('info', `death ledger loaded: deathCount=${state2.deathCount}, entries=${deathLedger2.length}`);
  } catch (err) {
    logLine('warn', `death ledger: no usable file at ${deathsFilePath} (${err?.code ?? err?.message ?? err}) — starting fresh`);
  }
}
loadDeaths2();
console.log('BOOT2 (after restart, reload):', JSON.stringify(state2), 'ledger entries:', deathLedger2.length, logs.pop());

// 4. corrupt file case
fs.writeFileSync(deathsFilePath, '{not valid json');
const state3 = { deathCount: 0, lastDeath: null };
function loadDeaths3() {
  try {
    const raw = JSON.parse(fs.readFileSync(deathsFilePath, 'utf8'));
    if (typeof raw?.deathCount === 'number') state3.deathCount = raw.deathCount;
  } catch (err) {
    logLine('warn', `death ledger: no usable file at ${deathsFilePath} (${err?.code ?? err?.message ?? err}) — starting fresh`);
  }
}
loadDeaths3();
console.log('BOOT3 (corrupt file):', JSON.stringify(state3), logs.pop());
EOF
