80	
81	// ---------------------------------------------------------------------------
82	// THE DRAGON: bot.pathfinder.goto() lies about "success" — confirmed by
83	// direct source read of mineflayer-pathfinder's own lib/goto.js + index.js:
84	//   1. `noPathListener` in lib/goto.js calls cleanup() with NO error whenever
85	//      `results.path.length === 0` — an empty path (e.g. a no-dig Movements
86	//      search that can't find a single step forward from the start node)
87	//      resolves the promise as a SUCCESS, not a NoPath rejection.
88	//   2. index.js only ever fires 'goal_reached' by checking
89	//      `stateGoal.isEnd(bot.entity.position.floored())` — a FLOORED integer
90	//      node, not the bot's real continuous position. A goal whose floor cell
91	//      already contains the bot's start position (loose range, or a target
92	//      that floors into the same cell) fires goal_reached with zero actual
93	//      movement, on the very first physics tick.
94	// Both paths resolve the goto() promise as if the goal were reached even
95	// though the bot never moved. gotoLoopPf below never trusted the resolved
96	// promise alone again — every "success" gets ground-truthed against
97	// bot.entity.position before being believed.
98	//
99	// Returns null when `goal` doesn't expose enough of x/y/z to ground-truth
100	// (e.g. a pure GoalY) — callers should skip verification in that case.
101	//
102	// (CALIBRATION) horizDist/vertDist split out separately from the old single
103	// 3D `dist` — field logs (Grog + Bonk) showed the combined-3D check flagging
104	// a real, close success as a false-reach whenever a GoalNear had a vertical
105	// offset baked in (mining/staircase targets almost always do): a bot well
106	// within lateral range but 1+ block above/below the goal's y got its 3D dist
107	// inflated past range+0.75 by the y term alone. horizDist now carries the
108	// x/z-only distance (what the range margin is actually meant to gate), and
109	// vertDist carries the y-only distance, checked against its own generous
110	// fixed slack — see call sites below. `dist` (full 3D) is kept for the one
111	// caller that still wants a plain "how close is close enough to bother with
112	// rawWalkTo" heuristic, unrelated to the reached/not-reached verdict.
113	function goalGroundTruth(bot, goal) {
114	  if (typeof goal?.x !== 'number' && typeof goal?.z !== 'number') return null;
115	  const pos = bot.entity.position;
116	  // (REACH-GAP FIX) GoalGetToBlock extends Goal directly — it has NO rangeSq,
117	  // so this used to ground-truth it as range 0, making every downstream
118	  // margin check (false-reach at range+1.0, rawWalkTo's stop condition)
119	  // demand <=1.0h from the block CENTER. Physically impossible whenever the
120	  // target's adjacent cell isn't standable: a bot pressed flush against the
121	  // next wall bottoms out at 1.0 (cell) + 0.5 (center) + 0.3 (body radius)
122	  // = exactly the fixed 1.80h shortfall in every field log. "Stand adjacent"
123	  // semantics = an effective range of 1.5, which puts the margin checks at
124	  // 2.5h — and the dig itself is still gated separately by skills.js's
125	  // ensureWithinReach 4.2 eye-distance law, so this loosens nothing unsafe.
126	  let range = 0;
127	  if (typeof goal.rangeSq === 'number') range = Math.sqrt(goal.rangeSq);
128	  else if (pfGoals?.GoalGetToBlock && goal instanceof pfGoals.GoalGetToBlock) range = 1.5;
129	  let horizDistSq = 0;
130	  if (typeof goal.x === 'number') {
131	    const dx = pos.x - (goal.x + 0.5);
132	    horizDistSq += dx * dx;
133	  }
134	  if (typeof goal.z === 'number') {
135	    const dz = pos.z - (goal.z + 0.5);
136	    horizDistSq += dz * dz;
137	  }
138	  const horizDist = Math.sqrt(horizDistSq);
139	  const vertDist = typeof goal.y === 'number' ? Math.abs(pos.y - goal.y) : 0;
140	  return { dist: Math.hypot(horizDist, vertDist), horizDist, vertDist, range };
141	}
142	
143	// Last-resort fallback once bot.pathfinder's own goto() has been caught
144	// false-reaching (or genuinely failing) across every retry AND the bot is
145	// still ground-truthed as actually close (<6 blocks — see call site).
146	// Bypasses pathfinder entirely: look at the target, pulse forward+jump in
147	// short (300ms) bursts, re-measuring real position after every pulse, until
148	// ground-truth horizontal distance clears range+1.0 (vertical within 1.5) or
149	// 15s elapses. Deliberately dumb
150	// (no obstacle avoidance, no digging) — only meant for the "goal is right
151	// there, pathfinder just isn't moving" case, never general navigation.
152	async function rawWalkTo(bot, goal, range, ctx) {
153	  const targetPos = new Vec3(
154	    typeof goal.x === 'number' ? goal.x + 0.5 : bot.entity.position.x,
155	    typeof goal.y === 'number' ? goal.y : bot.entity.position.y,
156	    typeof goal.z === 'number' ? goal.z + 0.5 : bot.entity.position.z
157	  );
158	  const deadline = Date.now() + 15000;
159	  try {
160	    while (Date.now() < deadline) {
161	      if (ctx.isCancelled?.()) throw new Error('rawWalkTo: cancelled');
162	      if (ctx.isStaleGeneration?.()) throw new Error('rawWalkTo: stale generation');
163	      const check = goalGroundTruth(bot, goal);
164	      if (check && check.horizDist <= check.range + 1.0 && check.vertDist <= 1.5) return;
165	      // (LOOK-WAKE LAW, Thak 2026-09-01 — FEEDBACK "setControlState no-op
166	      // without preceding bot.look()") The forced look packet is what makes
167	      // the control toggles below actually take effect; bare setControlState
168	      // measured zero movement across 3 test batches until a forced look was
169	      // put in front of it. lookAt(pos, true) is that forced look, sent once
170	      // per pulse here — the fallback keeps the law satisfied on the pulses
171	      // where lookAt itself throws.
172	      try {
173	        await bot.lookAt(targetPos, true);
174	      } catch {
175	        try {
176	          await bot.look(bot.entity.yaw, bot.entity.pitch, true);
177	        } catch {
178	          // ignore — still attempt to walk even if both look forms fail
179	        }
180	      }
181	      bot.setControlState('forward', true);
182	      bot.setControlState('jump', true);
183	      await sleep(300);
184	      bot.setControlState('forward', false);
185	      bot.setControlState('jump', false);
186	    }
187	  } finally {
188	    try {
189	      bot.setControlState('forward', false);
190	      bot.setControlState('jump', false);
191	    } catch {
192	      // ignore
193	    }
194	  }
195	  const finalCheck = goalGroundTruth(bot, goal);
196	  if (!finalCheck || finalCheck.horizDist > finalCheck.range + 1.0 || finalCheck.vertDist > 1.5) {
197	    throw new Error(
198	      `rawWalkTo: still ${finalCheck ? `${finalCheck.horizDist.toFixed(2)}h/${finalCheck.vertDist.toFixed(2)}v` : '?'} blocks from goal after 15s raw-walk`
199	    );
200	  }
201	}
202	
203	// Plain timeout race, no cancellation polling — this is the exact helper
204	// gotoLoopPf below used as skills.js's `withTimeout`, kept unchanged. The
205	// cancellation-aware version (raceWithCancelAndTimeout, further down) exists
206	// only for the ash engine, which has a real hang bug to work around (gotcha
207	// #2 in the file header); pf has no such bug, so gotoLoopPf keeps its
208	// original, already-proven-in-production behavior verbatim.
209	function withTimeout(promise, ms) {
210	  return new Promise((resolve, reject) => {
211	    const timer = setTimeout(() => reject(new Error(`timed out after ${ms}ms`)), ms);
212	    promise.then(
213	      (v) => {
214	        clearTimeout(timer);
215	        resolve(v);
216	      },
217	      (err) => {
218	        clearTimeout(timer);
219	        reject(err);
220	      }
221	    );
222	  });
223	}
