const DECHAT_PREFIXES = /^(TRADE |USING |FREE |LEASE-BREAK |BASE |CLAIM |HELLO |OFFER |DEPOT )/;
const logs = [];
function logLine(l, m) { logs.push(`[${l}] ${m}`); }
const sent = { chat: [], status: [] };
async function announceStub(style, text) {
  if (style !== 'status' && DECHAT_PREFIXES.test(String(text))) {
    logLine('warn', `announce: forcing style '${style}' -> 'status' for protocol-prefixed line: ${text.slice(0,60)}`);
    style = 'status';
  }
  if (style === 'status') { sent.status.push(text); return; }
  sent.chat.push({ style, text }); // fancy/rainbow real chat
}
async function smartChatStub(text) {
  const msg = String(text);
  if (msg.startsWith('!')) {
    const stripped = msg.slice(1).trim();
    if (DECHAT_PREFIXES.test(stripped)) {
      logLine('warn', `smartChat: forcing "!"-prefixed protocol line to status: ${stripped.slice(0,60)}`);
      await announceStub('status', stripped);
      return;
    }
    sent.chat.push({ style: '!', text: stripped });
    return;
  }
  await announceStub('status', msg);
}

const tests = [
  ['fancy bypass attempt', () => announceStub('fancy', 'TRADE take 3 leave 5')],
  ['rainbow bypass attempt', () => announceStub('rainbow', 'DEPOT +5 iron_ingot (chest A)')],
  ['legit fancy (no prefix)', () => announceStub('fancy', 'grand staircase reached y54!')],
  ['legit rainbow proclamation', () => announceStub('rainbow', 'cavecrew hits goal ladder step 6!')],
  ['!-prefixed protocol combo', () => smartChatStub('!USING crafting table at (12,89,56)')],
  ['plain ! real talk', () => smartChatStub('!HP 6/20 - breaking off, reacting to danger!')],
  ['ordinary talk narration', () => smartChatStub('heading out to chop wood')],
];
for (const [label, fn] of tests) { await fn(); }
console.log('sent.chat (should ONLY contain the 2 legit lines):', JSON.stringify(sent.chat, null, 2));
console.log('sent.status count:', sent.status.length, '(should be 4: 2 forced-down + 1 !-forced + 1 plain narration)');
console.log(logs.join('\n'));
EOF
