cat > /tmp/craftloop_test.mjs << 'EOF'
// Simulate the fixed craftItem loop against a fake bot that reproduces
// Thak's exact bug: bot.craft(recipe, N>1) crafts 1 then the recipe becomes
// stale and any reuse throws "missing ingredient" -- but a FRESH recipesFor()
// call + single craft(1) each time succeeds as long as real materials remain.
function makeFakeBot(stock) {
  let craftCalls = 0;
  return {
    craft: async (recipe, count) => {
      craftCalls++;
      if (count !== 1) throw new Error('test only models single-craft calls');
      if (recipe._stale) throw new Error('missing ingredient'); // old bug: reused recipe object
      if (stock.coal <= 0 || stock.stick <= 0) throw new Error('missing ingredient');
      stock.coal--; stock.stick--; stock.torch = (stock.torch||0) + 4;
    },
    recipesFor: () => (stock.coal > 0 && stock.stick > 0) ? [{ _stale: false }] : [],
    calls: () => craftCalls,
  };
}
async function fixedCraftLoop(bot, amount) {
  for (let i = 0; i < amount; i++) {
    const recipes = bot.recipesFor();
    if (recipes.length === 0) throw new Error(`ran out after ${i}/${amount} crafted`);
    await bot.craft(recipes[0], 1);
  }
}
const stock = { coal: 10, stick: 10, torch: 0 };
const bot = makeFakeBot(stock);
await fixedCraftLoop(bot, 10);
console.log('after 10x torch craft:', JSON.stringify(stock), 'craft() calls:', bot.calls());
console.log(stock.torch === 40 && stock.coal === 0 && stock.stick === 0 ? 'PASS: full batch succeeded' : 'FAIL');

// exhaustion case: ask for more than materials allow
const stock2 = { coal: 3, stick: 3, torch: 0 };
const bot2 = makeFakeBot(stock2);
try {
  await fixedCraftLoop(bot2, 10);
  console.log('FAIL: should have thrown');
} catch (err) {
  console.log('exhaustion case threw as expected:', err.message, '| partial progress:', JSON.stringify(stock2));
}
EOF
node /tmp/craftloop_test.mjs
rm /tmp/craftloop_test.mjs

