const CROP_BLOCKS = /^(wheat|carrots|potatoes|beetroots)$/;
const DROP_NEIGHBOR_OFFSETS = [
  { x: 1, y: 0, z: 0 }, { x: -1, y: 0, z: 0 },
  { x: 0, y: 0, z: 1 }, { x: 0, y: 0, z: -1 },
  { x: 0, y: 1, z: 0 }, { x: 0, y: -1, z: 0 },
];

// Fake world: a dict of "x,y,z" -> block name
function makeWorld(map) {
  return (p) => map[`${p.x},${p.y},${p.z}`] ?? 'air';
}
function offset(p, o) { return { x: p.x + o.x, y: p.y + o.y, z: p.z + o.z }; }
function key(p) { return `${p.x},${p.y},${p.z}`; }

function planAttempts(dest, blockAt) {
  const isCropProtected = (p) => CROP_BLOCKS.test(blockAt(p));
  const attempts = [dest, ...DROP_NEIGHBOR_OFFSETS.map((o) => offset(dest, o))];
  const kept = [];
  let skipped = 0;
  for (const c of attempts) {
    if (isCropProtected(c)) { skipped++; continue; }
    kept.push(c);
  }
  return { kept, skipped, total: attempts.length };
}

// Case 1: Zug's exact incident — drop sits exactly on a live crop tile (7,89,59)
const world1 = makeWorld({ '7,89,59': 'wheat', '8,89,59': 'grass_block', '6,89,59': 'wheat', '7,90,59': 'air', '7,88,59': 'farmland' });
const r1 = planAttempts({ x: 7, y: 89, z: 59 }, world1);
console.log('Case 1 (drop on crop):', r1, '-> dest excluded from attempts?', !r1.kept.some(p => key(p) === '7,89,59'));

// Case 2: ordinary drop, no crop anywhere nearby — everything kept, unchanged behavior
const world2 = makeWorld({});
const r2 = planAttempts({ x: 20, y: 89, z: 30 }, world2);
console.log('Case 2 (no crops nearby):', r2.kept.length, '/', r2.total, 'kept, 0 skipped ->', r2.skipped === 0 && r2.kept.length === r2.total ? 'PASS unchanged' : 'FAIL');

// Case 3: pathological — every candidate is crop (dense field), all skipped
const denseMap = {};
for (const o of [{x:0,y:0,z:0}, ...DROP_NEIGHBOR_OFFSETS]) denseMap[key(offset({x:5,y:89,z:5}, o))] = 'wheat';
const r3 = planAttempts({ x: 5, y: 89, z: 5 }, makeWorld(denseMap));
console.log('Case 3 (all 7 candidates crop):', r3, '-> kept.length===0?', r3.kept.length === 0, ', skipped===7?', r3.skipped === 7);
